import os
import io
from typing import Any, Dict, List, Optional, Union

import boto3


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace(",", "")
    if not text:
        return None
    filtered = "".join(ch for ch in text if ch.isdigit() or ch in ".-")
    if filtered in {"", ".", "-", "-."}:
        return None
    try:
        return float(filtered)
    except ValueError:
        return None


def _normalize_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _extract_summary_fields(summary_fields: List[Dict[str, Any]]) -> Dict[str, Any]:
    result: Dict[str, Any] = {
        "merchant": None,
        "tax": None,
        "total": None,
    }

    merchant_candidates = []
    tax_candidates = []
    total_candidates = []

    for field in summary_fields:
        field_type = field.get("Type", {}).get("Text")
        value_detection = field.get("ValueDetection", {})
        value_text = value_detection.get("Text")
        value_number = value_detection.get("NormalizedValue", {}).get("Value")

        if field_type in {"VENDOR_NAME", "RECEIVER_NAME"}:
            merchant = _normalize_text(value_text)
            if merchant:
                merchant_candidates.append(merchant)

        elif field_type in {"TAX", "TOTAL_TAX"}:
            tax_value = _to_float(value_number if value_number is not None else value_text)
            if tax_value is not None:
                tax_candidates.append(tax_value)

        elif field_type in {"TOTAL", "AMOUNT_DUE", "BALANCE"}:
            total_value = _to_float(value_number if value_number is not None else value_text)
            if total_value is not None:
                total_candidates.append(total_value)

    if merchant_candidates:
        result["merchant"] = merchant_candidates[0]
    if tax_candidates:
        result["tax"] = tax_candidates[0]
    if total_candidates:
        result["total"] = max(total_candidates)

    return result


def _extract_items(line_item_groups: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    for group in line_item_groups:
        for line_item in group.get("LineItems", []):
            item: Dict[str, Any] = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "total_price": None,
            }

            for field in line_item.get("LineItemExpenseFields", []):
                field_type = field.get("Type", {}).get("Text")
                value_detection = field.get("ValueDetection", {})
                value_text = value_detection.get("Text")
                value_number = value_detection.get("NormalizedValue", {}).get("Value")

                if field_type in {"ITEM", "DESCRIPTION"}:
                    item["description"] = _normalize_text(value_text)
                elif field_type == "QUANTITY":
                    item["quantity"] = _to_float(value_number if value_number is not None else value_text)
                elif field_type in {"PRICE", "UNIT_PRICE"}:
                    item["unit_price"] = _to_float(value_number if value_number is not None else value_text)
                elif field_type in {"AMOUNT", "LINE_TOTAL"}:
                    item["total_price"] = _to_float(value_number if value_number is not None else value_text)

            if any(v is not None for v in item.values()):
                items.append(item)

    return items


def extract_receipt_fields(
    file_path: Optional[str] = None,
    file_bytes: Optional[Union[bytes, bytearray, io.BytesIO]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    if not file_path and file_bytes is None:
        raise ValueError("Provide either file_path or file_bytes.")

    if file_bytes is not None:
        if isinstance(file_bytes, io.BytesIO):
            document_bytes = file_bytes.getvalue()
        else:
            document_bytes = bytes(file_bytes)
    else:
        with open(file_path, "rb") as f:
            document_bytes = f.read()

    client = boto3.client(
        "textract",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
    )

    response = client.analyze_expense(Document={"Bytes": document_bytes})

    merchant = None
    tax = None
    total = None
    items: List[Dict[str, Any]] = []

    for expense_document in response.get("ExpenseDocuments", []):
        summary = _extract_summary_fields(expense_document.get("SummaryFields", []))
        if merchant is None and summary["merchant"] is not None:
            merchant = summary["merchant"]
        if tax is None and summary["tax"] is not None:
            tax = summary["tax"]
        if total is None and summary["total"] is not None:
            total = summary["total"]

        extracted_items = _extract_items(expense_document.get("LineItemGroups", []))
        if extracted_items:
            items.extend(extracted_items)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
